const ART = Object.freeze({
 '/assets/hotel.png':'hotelview.png','/assets/lobby.png':'lobby.png',
 '/assets/rooftop.png':'rooftop.png','/assets/picnic.png':'picnic.png',
 '/assets/peacefulpark.png':'peacefulpark.png','/assets/rooftop_pool.png':'rooftop_pool.png'
});
const ART_BASE='https://raw.githubusercontent.com/JoshuaDeGreat/polaris-emulator/f5a4318437efb73e02048a7286785222da19a0c6/Assets/images/reception/';
const STAFF_API_ORIGIN='https://polaris-polaris-hotel.up.railway.app';
const STAFF_SECURITY={'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','X-Frame-Options':'DENY','X-Robots-Tag':'noindex, nofollow','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline' https://challenges.cloudflare.com; style-src 'self' 'unsafe-inline'; img-src 'self' https: data:; connect-src 'self' https://challenges.cloudflare.com; frame-src https://challenges.cloudflare.com; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'"};
function staffError(status,error){return new Response(JSON.stringify({error}),{status,headers:{...STAFF_SECURITY,'Content-Type':'application/json; charset=utf-8'}});}
async function staffBody(request,max){
 if(Number(request.headers.get('content-length'))>max)throw Error('too-large');
 if(!request.body)return new Uint8Array();
 const reader=request.body.getReader(),chunks=[];let n=0;
 try{for(;;){const{done,value}=await reader.read();if(done)break;n+=value.byteLength;if(n>max){await reader.cancel();throw Error('too-large');}chunks.push(value);}}finally{reader.releaseLock();}
 const body=new Uint8Array(n);let offset=0;for(const chunk of chunks){body.set(chunk,offset);offset+=chunk.byteLength;}return body;
}
async function staffRoute(request,page,fetcher=fetch){
 const url=new URL(request.url),path=url.pathname;
 if(path==='/staff/'||path==='/community/staff')return new Response(null,{status:308,headers:{...STAFF_SECURITY,Location:'/staff'}});
 if(path==='/staff'){
  if(!['GET','HEAD'].includes(request.method))return staffError(405,'Use GET or HEAD.');
  return new Response(request.method==='HEAD'?null:page,{headers:{...STAFF_SECURITY,'Content-Type':'text/html; charset=utf-8'}});
 }
 const login=path==='/api/auth/login',news=path==='/api/community/staff/news';
 if(!login&&!news)return null;
 if((login&&request.method!=='POST')||(news&&!['GET','POST'].includes(request.method)))return staffError(405,'Method not allowed.');
 // Validate the real browser origin before translating it to the fixed upstream.
 // Polaris retains every token, online Housekeeping permission and lockdown gate.
 if(request.method==='POST'&&request.headers.get('origin')!==url.origin)return staffError(403,'Open the staff area on this website before signing in or saving.');
 if(request.method==='POST'&&!/^application\/json(?:\s*;|$)/i.test(request.headers.get('content-type')||''))return staffError(415,'Use JSON.');
 const auth=request.headers.get('authorization')||'';
 if(news&&!/^Bearer \S+$/.test(auth))return staffError(403,'Sign in with an authorized staff account.');
 let body;if(request.method==='POST'){try{body=await staffBody(request,login?8192:50000);}catch{return staffError(413,'Request is too large.');}}
 const headers=new Headers({Accept:'application/json'});if(news)headers.set('Authorization',auth);
 if(request.method==='POST'){headers.set('Content-Type','application/json');headers.set('Origin',STAFF_API_ORIGIN);}
 try{
  const response=await fetcher(STAFF_API_ORIGIN+path,{method:request.method,headers,body,redirect:'manual',signal:AbortSignal.timeout(15000)});
  if(response.status>=300&&response.status<400)return staffError(502,'Unexpected staff service redirect.');
  // Deliberately omit upstream cookies, CORS and cache headers.
  return new Response(response.body,{status:response.status,headers:{...STAFF_SECURITY,'Content-Type':response.headers.get('Content-Type')||'application/json; charset=utf-8'}});
 }catch{return staffError(502,'The staff service is temporarily unavailable. Please try again.');}
}

const WEBSITE_UPSTREAM='https://polaris-polaris-hotel.up.railway.app';
const COOKIE='__Host-heaven_session';
const clearCookie=()=>COOKIE+'=; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=0';
function websiteCookie(request){
 const values=(request.headers.get('cookie')||'').split(';').map(s=>s.trim()).filter(s=>s.startsWith(COOKIE+'='));
 if(values.length!==1)return '';
 const value=values[0].slice(COOKIE.length+1);return /^hws_[A-Za-z0-9_-]{43}$/.test(value)?value:'';
}
async function memberRoute(request,page,fetcher=fetch){
 const url=new URL(request.url),path=url.pathname;
 if(path==='/login'||path==='/account/')return new Response(null,{status:308,headers:{...STAFF_SECURITY,Location:'/account'}});
 if(path==='/account'){
  if(!['GET','HEAD'].includes(request.method))return staffError(405,'Use GET or HEAD.');
  return new Response(request.method==='HEAD'?null:page,{headers:{...STAFF_SECURITY,'Content-Type':'text/html; charset=utf-8'}});
 }
 if(path==='/api/community/staff/news'){
  const token=websiteCookie(request);if(!token){if(request.headers.has('authorization'))return staffRoute(request,'',fetcher);return staffError(401,'Please sign in to your account.');}
  const headers=new Headers(request.headers);headers.set('Authorization','Bearer '+token);return staffRoute(new Request(request,{headers}),'',fetcher);
 }
 const routes={'/api/site/login':['POST','/api/auth/website-login',false],'/api/site/recovery':['POST','/api/auth/forgot-password',false],'/api/site/account':['GET','/api/community/account',true],'/api/site/logout':['POST','/api/community/account/logout',true],'/api/site/verify-email':['POST','/api/community/account/verify-email',true]};
 if(!Object.hasOwn(routes,path))return null;
 const[method,target,privateRoute]=routes[path];if(request.method!==method)return staffError(405,'Method not allowed.');
 if(method==='POST'&&request.headers.get('origin')!==url.origin)return staffError(403,'Open your account on this website before continuing.');
 if(method==='POST'&&!/^application\/json(?:\s*;|$)/i.test(request.headers.get('content-type')||''))return staffError(415,'Use JSON.');
 const token=websiteCookie(request);if(privateRoute&&!token)return staffError(401,'Please sign in to your account.');
 let body;if(method==='POST'){try{body=await staffBody(request,8192);}catch{return staffError(413,'Request is too large.');}}
 const headers=new Headers({Accept:'application/json'});if(privateRoute)headers.set('Authorization','Bearer '+token);if(method==='POST'){headers.set('Origin',WEBSITE_UPSTREAM);headers.set('Content-Type','application/json');}
 try{
  const response=await fetcher(WEBSITE_UPSTREAM+target,{method,headers,body,redirect:'manual',signal:AbortSignal.timeout(15000)});
  if(response.status>=300&&response.status<400)return staffError(502,'The account service returned an unexpected redirect.');
  const resultHeaders=new Headers({...STAFF_SECURITY,'Content-Type':'application/json; charset=utf-8'});
  if(response.status===401)resultHeaders.set('Set-Cookie',clearCookie());
  if(path==='/api/site/login'&&response.ok){
   const data=await response.json();if(!/^hws_[A-Za-z0-9_-]{43}$/.test(data.accessToken||''))return staffError(502,'The account service returned an invalid session.');
   const age=Math.min(1800,Math.floor(Number(data.accessTokenExpiresAt)-Date.now()/1000));if(!(age>0))return staffError(502,'The account session has expired. Please try again.');
   resultHeaders.set('Set-Cookie',COOKIE+'='+data.accessToken+'; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age='+age);
   return new Response('{"ok":true}',{headers:resultHeaders});
  }
  if(path==='/api/site/logout'&&response.ok)resultHeaders.set('Set-Cookie',clearCookie());
  return new Response(response.body,{status:response.status,headers:resultHeaders});
 }catch{return staffError(502,'Your account is temporarily unavailable. Please try again.');}
}

const STAFF_PAGE="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Heaven • News desk</title><style>\n:root{color-scheme:light;--ink:#304550;--line:#527080;--paper:#fffdf4;--blue:#267d9c}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:linear-gradient(#79b9d1,#b4dae4 480px,#dbe9e1);color:var(--ink);font:15px/1.65 'Trebuchet MS',Arial,sans-serif}a{color:#236c88;text-underline-offset:3px}button,input,textarea{font:inherit}button,a{-webkit-tap-highlight-color:transparent}[hidden]{display:none!important}.shell{width:calc(100% - 40px);max-width:1120px;margin:auto;position:relative;z-index:1}.brand-bar{min-height:144px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand-bar img{width:250px;max-width:100%;height:auto;display:block}.home-link{background:var(--paper);border:2px solid var(--line);border-radius:6px;padding:9px 17px;box-shadow:0 3px #4f8095;text-decoration:none;font-size:13px;font-weight:bold}.staff-intro{display:flex;align-items:center;gap:14px;margin:4px 0 25px}.staff-intro h1{font-size:34px;letter-spacing:-1px;line-height:1.2;margin:0 0 7px;color:#304f60}.staff-intro p{margin:0;color:#3c6171}.staff-tag{display:inline-block;font-size:10px;letter-spacing:1.2px;font-weight:bold;color:#5b6248;background:#fff2c8;border:1px solid #c8b078;padding:3px 9px;border-radius:4px;margin-bottom:10px}main{padding-bottom:24px}.window{overflow:hidden;background:var(--paper);border:2px solid var(--line);border-radius:9px;box-shadow:0 4px #496b7c,0 12px 24px #31566c18}.window-bar{background:linear-gradient(#5aa1bc,#2d748e);box-shadow:inset 0 1px #c4e7f1;border-bottom:2px solid #486473;padding:8px 16px;color:#fff;font-size:12px;font-weight:bold;display:flex;align-items:center;justify-content:space-between;min-height:38px;text-shadow:0 1px #284c60}.window-bar h2{font:inherit;margin:0}.window-body{padding:26px}.cream-bar{background:linear-gradient(#faf2d9,#e8ddbd);color:#655b42;text-shadow:0 1px #fff;border-bottom:1px solid #c4b797;box-shadow:inset 0 1px white}h2{font-size:23px;line-height:1.3;margin:0 0 10px;color:#344d59}p{color:#536971;margin:0 0 16px}label{display:block;font-size:13px;font-weight:bold;margin:17px 0 7px}input,textarea{width:100%;border:2px solid #a5b6b7;border-radius:5px;color:var(--ink);background:white;padding:11px 12px;box-shadow:inset 0 2px #e5ebea;min-height:46px}textarea{min-height:210px;resize:vertical;line-height:1.7}input:focus,textarea:focus{border-color:#367f9a;outline:3px solid #e5c469;outline-offset:2px}button{border:2px solid #336b86;border-radius:6px;background:linear-gradient(#49add0,#2589b1 48%,#19749d 50%,#206d90);box-shadow:inset 0 1px #b5e9f8,0 3px #355a6d;color:white;padding:10px 17px;font-weight:bold;cursor:pointer;min-height:44px}button:hover{filter:brightness(1.05)}button:disabled{opacity:.55;cursor:wait}button.secondary{background:linear-gradient(#fff4ce,#ead5a0);border-color:#b4a070;box-shadow:inset 0 1px white,0 3px #c1ae80;color:#5c5138}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:20px}.row label{margin:0}.row input[type=checkbox]{width:20px;min-height:20px;box-shadow:none;accent-color:#267d9c}.note{font-size:12px;color:#626f64;margin-top:18px}.note a{font-weight:bold}.signin-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.signin-copy{padding:32px}.signin-art{position:relative;display:flex;flex-direction:column;justify-content:center;align-items:center;overflow:hidden;background:radial-gradient(ellipse at 70% 25%,#e3f2ed,transparent 75%);padding:22px 15px;background-color:#edf3e8}.signin-art img{width:410px;max-width:115%;height:auto}.signin-art strong{display:block;color:#3b5a68;font-size:18px;margin:15px 0 5px}.signin-art p{text-align:center;font-size:12px;max-width:260px;margin:0}.signin-copy #signIn{width:100%}.signin-copy h2{font-size:28px}#staffTurnstile{margin-top:20px;min-height:65px;overflow-x:auto}.grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:22px;align-items:start}.article{display:block;width:100%;background:#f7f0dd;border:1px solid #d7c9a8;border-radius:5px;box-shadow:0 2px #ded3b8;color:#344d59;text-align:left;overflow-wrap:anywhere;padding:13px;margin-top:14px}.article small{display:block;color:#6a7061;font-size:11px;margin-top:6px}.article[aria-current=true]{outline:3px solid #3d88a3;outline-offset:1px}.editor-toolbar{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap;margin-bottom:20px;background:#eaf4efd9;border:1px solid #9fbcc3;border-radius:6px;padding:13px 18px}.editor-toolbar p{margin:0;font-size:13px}.editor-toolbar strong{display:block;color:#34596b}.editor-toolbar button{font-size:12px}.field-pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}.publish-row{background:#f4ecd6;border:1px solid #d7c8a5;border-radius:5px;padding:13px 15px}.actions{border-top:1px dashed #d5cbb1;padding-top:20px}#message{white-space:pre-line;overflow-wrap:anywhere;margin:20px 0 0;padding:0;min-height:0}#message:not(:empty){padding:14px 18px;background:#fff5da;border:1px solid #bcaa7b;border-radius:5px;margin-bottom:22px;font-size:14px}#preview{margin-top:24px;background:#f4f3e7;border:1px dashed #b4a579;padding:22px;border-radius:6px;white-space:pre-wrap;overflow-wrap:anywhere}#preview img{display:block;max-width:100%;max-height:240px;height:auto;margin-bottom:14px;border-radius:4px}#preview h2{margin:6px 0 14px}.site-footer{text-align:center;padding:12px 15px 30px;color:#52727d;font-size:11px}.site-footer p{margin:0 0 5px;font-size:12px}.site-footer small{font-size:10px}.sky-cloud{position:absolute;width:140px;height:30px;background:#ffffff55;top:180px;left:2%;pointer-events:none}.sky-cloud:before,.sky-cloud:after{content:'';position:absolute;bottom:18px;background:inherit}.sky-cloud:before{width:55px;height:35px;left:20px}.sky-cloud:after{width:40px;height:20px;left:75px}:focus-visible{outline:3px solid #bb871d;outline-offset:4px}@media(max-width:760px){.shell{width:calc(100% - 28px)}.brand-bar{min-height:115px;gap:10px}.brand-bar img{width:190px}.home-link{font-size:11px;padding:8px 10px}.staff-intro h1{font-size:29px}.staff-intro p{font-size:13px}.signin-grid,.grid{grid-template-columns:1fr}.signin-copy,.window-body{padding:23px}.signin-art{padding:8px 16px 22px}.signin-art img{width:280px;margin-top:-25px}.signin-art strong{margin-top:0}.field-pair{grid-template-columns:1fr;gap:0}.editor-toolbar{padding:14px}.window-bar{padding:8px 13px}.actions button{flex:1}.row{gap:10px}}\n</style><script defer src=\"https://challenges.cloudflare.com/turnstile/v0/api.js?onload=initStaffTurnstile&amp;render=explicit\"></script></head><body><div class=\"sky-cloud\" aria-hidden=\"true\"></div><div class=\"shell\"><header class=\"brand-bar\"><a href=\"https://heavenhotel.uk/\" aria-label=\"Heaven Hotel home\"><img src=\"https://heavenhotel.uk/assets/heaven-logo.svg\" alt=\"Heaven Hotel — Your world above the clouds\" width=\"250\" height=\"108\"></a><a class=\"home-link\" href=\"https://heavenhotel.uk/account\">My account ↗</a></header><div class=\"staff-intro\"><div><span class=\"staff-tag\">HEAVEN HOTEL · STAFF AREA</span><h1>The news desk.</h1><p>A little news, a big welcome. Keep the hotel noticeboard up to date.</p></div></div><main><section id=\"login\" class=\"window\"><div class=\"window-bar\"><span>WELCOME TO THE STAFF AREA</span><span aria-hidden=\"true\">▣</span></div><div class=\"signin-grid\"><div class=\"signin-copy\"><h2>Staff sign-in</h2><p>Use your existing hotel account. Staff permissions are checked against your hotel account. You do not need to keep the game open.</p><form id=\"loginForm\"><label for=\"username\">Hotel username</label><input id=\"username\" autocomplete=\"username\" required maxlength=\"32\"><label for=\"password\">Password</label><input id=\"password\" type=\"password\" autocomplete=\"current-password\" required><div id=\"staffTurnstile\" aria-label=\"Security verification\"></div><div class=\"row\"><button id=\"signIn\">Open the news desk →</button></div></form><p class=\"note\">Your editor session clears when this page closes. <a href=\"https://play.heavenhotel.uk/\" target=\"_blank\" rel=\"noopener\">Open the hotel ↗</a></p></div><aside class=\"signin-art\"><img src=\"https://heavenhotel.uk/assets/hotel.png\" alt=\"Heaven Hotel with rooftop gardens and a swimming pool\" width=\"1256\" height=\"990\"><strong>A little place to call home.</strong><p>Share the moments, events and stories that bring Heaven together.</p></aside></div></section><div id=\"message\" role=\"status\" aria-live=\"polite\"></div>\n<div id=\"editor\" hidden><div class=\"editor-toolbar\"><p><strong>News &amp; announcements</strong>Published stories appear on the homepage and hotel login.</p><button class=\"secondary\" id=\"signOut\">Close editor session</button></div><div class=\"grid\"><aside class=\"window\"><div class=\"window-bar cream-bar\"><h2>Your stories</h2><span aria-hidden=\"true\">✉</span></div><div class=\"window-body\"><button id=\"newArticle\">＋ New article</button><div id=\"articles\"></div></div></aside><section class=\"window\"><div class=\"window-bar\"><span>HOTEL NOTICEBOARD</span><span aria-hidden=\"true\">▣</span></div><div class=\"window-body\"><form id=\"articleForm\"><h2 id=\"formTitle\">New article</h2><input id=\"articleId\" type=\"hidden\" value=\"0\"><label for=\"title\">Title</label><input id=\"title\" maxlength=\"150\" required><label for=\"body\">Story</label><textarea id=\"body\" maxlength=\"20000\" required></textarea><label for=\"image\">Image URL (optional, HTTPS)</label><input id=\"image\" type=\"url\" maxlength=\"255\" placeholder=\"https://…\"><div class=\"field-pair\"><div><label for=\"linkText\">Link text (optional)</label><input id=\"linkText\" maxlength=\"80\"></div><div><label for=\"linkUrl\">Link URL (optional, HTTPS)</label><input id=\"linkUrl\" type=\"url\" maxlength=\"255\" placeholder=\"https://…\"></div></div><label for=\"sortOrder\">Display order (lower comes first)</label><input id=\"sortOrder\" type=\"number\" min=\"0\" max=\"100000\" value=\"0\" required><div class=\"row publish-row\"><input id=\"enabled\" type=\"checkbox\"><label for=\"enabled\">Published — visible to players</label></div><p class=\"note\">Leave unpublished to save a draft or hide an older article. Saving does not delete articles.</p><div class=\"row actions\"><button id=\"save\">Save article</button><button id=\"showPreview\" type=\"button\" class=\"secondary\">Preview</button></div></form><div id=\"preview\" hidden aria-live=\"polite\"></div></div></section></div></div>\n</main><footer class=\"site-footer\"><p>Heaven Hotel · Your world above the clouds.</p><small>Staff access is checked against your hotel permissions.</small></footer></div><script>\n(()=>{'use strict';const $=s=>document.querySelector(s);const website=location.pathname==='/staff';let token='',articles=[];let staffTurnstileToken='',staffWidgetId=null;window.initStaffTurnstile=()=>{if(!window.turnstile)return;staffWidgetId=window.turnstile.render('#staffTurnstile',{sitekey:'0x4AAAAAAFaUUvcgD5oePRSO',theme:'light',callback:(value)=>{staffTurnstileToken=value;},'expired-callback':()=>{staffTurnstileToken='';},'error-callback':()=>{staffTurnstileToken='';message('Verification did not complete. Please refresh and try again.');}});};function resetStaffTurnstile(){staffTurnstileToken='';if(staffWidgetId!==null&&window.turnstile){try{window.turnstile.reset(staffWidgetId)}catch{}}}const fields=['title','body','image','linkText','linkUrl','sortOrder','enabled'];function message(t){$('#message').textContent=t}async function api(path,body,withToken=true){const headers={'Content-Type':'application/json'};if(withToken&&!website)headers.Authorization='Bearer '+token;const r=await fetch(path,{method:body?'POST':'GET',headers,cache:'no-store',credentials:website?'same-origin':'omit',signal:AbortSignal.timeout(12000),...(body?{body:JSON.stringify(body)}:{})});let d;try{d=await r.json()}catch{throw Error('The hotel returned an unexpected response. Try again.')}if(!r.ok)throw Object.assign(Error(typeof d.error==='string'?d.error:'The request could not be completed.'),{status:r.status});return d}function reset(){for(const f of fields)$('#'+f).value='';$('#articleId').value='0';$('#sortOrder').value='0';$('#enabled').checked=false;$('#formTitle').textContent='New article';$('#preview').hidden=true}function list(d){articles=d.articles;$('#articles').replaceChildren();for(const a of articles){const b=document.createElement('button');b.className='article';b.type='button';const t=document.createElement('strong');t.textContent=a.title;const s=document.createElement('small');s.textContent=(a.enabled?'Published':'Draft / hidden')+' · Order '+a.sortOrder;b.append(t,s);b.onclick=()=>{reset();$('#articleId').value=a.id;$('#formTitle').textContent='Edit article';for(const f of fields){if(f==='enabled')$('#'+f).checked=a[f];else $('#'+f).value=a[f]??''}message('Editing '+a.title)};$('#articles').append(b)}}$('#loginForm').onsubmit=async e=>{e.preventDefault();if(!staffTurnstileToken){message('Complete the Cloudflare security verification before signing in.');return;}$('#signIn').disabled=true;message('Checking your staff permissions…');try{const d=await api('/api/auth/login',{username:$('#username').value,password:$('#password').value,remember:false,turnstileToken:staffTurnstileToken},false);$('#password').value='';token=d.accessToken;list(await api('/api/community/staff/news'));$('#login').hidden=true;$('#editor').hidden=false;reset();message('News desk ready. Drafts stay private until Published is selected.')}catch(e){token='';$('#password').value='';message(e.message)}finally{resetStaffTurnstile();$('#signIn').disabled=false}};$('#signOut').onclick=()=>{if(website){location.assign('/account');return;}token='';articles=[];$('#articles').replaceChildren();$('#editor').hidden=true;$('#login').hidden=false;reset();message('Editor session closed. Your hotel session is unchanged.')};$('#newArticle').onclick=()=>{reset();message('New draft. Add your title and story.')};$('#articleForm').onsubmit=async e=>{e.preventDefault();if(!token){message('Sign in again.');return}const payload={id:Number($('#articleId').value)};for(const f of fields)payload[f]=f==='enabled'?$('#'+f).checked:f==='sortOrder'?Number($('#'+f).value):$('#'+f).value;$('#save').disabled=true;message('Saving…');try{list(await api('/api/community/staff/news',payload));reset();message(payload.enabled?'Article published. It will appear on the homepage shortly.':'Draft saved. It is hidden from players.')}catch(e){message(e.message)}finally{$('#save').disabled=false}};$('#showPreview').onclick=()=>{const p=$('#preview');p.replaceChildren();try{const u=new URL($('#image').value);if(u.protocol==='https:'){const i=document.createElement('img');i.src=u.href;i.alt='Article image';p.append(i)}}catch{}const h=document.createElement('h2');h.textContent=$('#title').value;const b=document.createElement('p');b.textContent=$('#body').value;p.append(h,b);p.hidden=false};if(website){$('#login').hidden=true;$('#signOut').textContent='Back to my account';message('Checking your staff access…');api('/api/site/account',null,false).then(async profile=>{if(!profile.canEditNews){message('Your account does not have access to the news desk. Return to your account to continue.');return;}list(await api('/api/community/staff/news'));$('#editor').hidden=false;reset();message('News desk ready. Drafts stay private until Published is selected.');}).catch(e=>{if(e.status===401)location.replace('/account?next=staff');else message(e.message);});} })();\n</script></body></html>\n";
